/**
 * @distilled.cloud/typesafe-ai — TypeSafe AI SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * in `.generated-specs` (written by `scripts/convert.ts` from the OpenAPI
 * spec). Everything else in this folder is hand-written.
 *
 * @example
 * ```ts
 * import * as TypesafeAi from "@distilled.cloud/typesafe-ai";
 *
 * const { answers } = yield* TypesafeAi.systemOne({
 *   state: "I was charged twice. Please help.",
 *   model: "jev-latest",
 *   questions: {
 *     billing: TypesafeAi.noul("Is this about billing?"),
 *   },
 * });
 * ```
 *
 * Pass an Effect `Schema.Struct` to {@link query} to derive questions from
 * field types (`Boolean` → noul, string literals → choice, {@link Score}
 * → score) and decode answers back into the schema's type.
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  TypesafeAiProtocol,
  type TypesafeAiOpError,
  type TypesafeAiOpContext,
} from "./protocol.ts";
export { paginateCursor } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
// Operations (and their request/response types) are importable straight off
// the package root. The service-local typed error classes shadow the
// same-named shared ones from ./errors.ts — the ops actually raise the
// service-local classes.
export * from "./services/typesafe-ai.ts";
export { UnprocessableEntity } from "./services/typesafe-ai.ts";
export * from "./questions.ts";
export * from "./query.ts";
export * from "./schema.ts";
